        addRelative(brother, 'Brother');
        addRelative(sister, 'Sister');

        people.push({
            FirstName: firstName,
            LastName: lastName,
            Birthday: birthdayFormatted,
            Age: age,
            Relatives: relatives
        });
    }

    console.log(JSON.stringify(people, null, 2));
}

