	if err != nil {
		fmt.Fprintf(os.Stderr, "Error reading CSV: %v\n", err)
		os.Exit(1)
	}

	if len(records) == 0 {
		fmt.Println("[]")
		return
	}

	// Skip header
	var people []Person
	for _, row := range records[1:] {
		if len(row) < 4 {
			continue
		}
		name := row[0]
		age, err1 := strconv.Atoi(row[1])
		email := row[2]
		score, err2 := strconv.ParseFloat(row[3], 64)
		if err1 != nil || err2 != nil {
			continue
		}
		people = append(people, Person{
			Name:  name,
			Age:   age,
			Email: email,
			Score: score,
		})
