Let me think about the test cases:

1. Quantity < 10 (e.g., quantity=9): no discount, total = price * 9
2. Quantity = 10 (boundary): 10% discount (0.9 multiplier), total = price * 10 * 0.9
3. Quantity = 49 (boundary): still 10% discount, total = price * 49 * 0.9
4. Quantity = 50 (boundary): 25% discount (0.75 multiplier), total = price * 50 * 0.75
5. Quantity > 50 (e.g., quantity=100): 25% discount, total = price * 100 * 0.75

Let me use a fixed price of 10.0 for clean numbers:
- qty=9: 10 * 9 = 90.0
- qty=10: 10 * 10 * 0.9 = 90.0
- qty=49: 10 * 49 * 0.9 = 441.0
- qty=50: 10 * 50 * 0.75 = 375.0
- qty=100: 10 * 100 * 0.75 = 750.0

That's 5 test cases covering all boundaries.
</think>

```csharp
double CalculateDiscount(double price, int quantity) {
    if (quantity < 10) return price * quantity;
    else if (quantity < 50) return price * quantity * 0.9;
    else return price * quantity * 0.75;
}

double price = 10.0;
double tolerance = 1e-9;

var tests = new (string desc, double price, int qty, double expected)[] {
    ("quantity=9 (below first threshold)", 10.0, 9, 10.0 * 9),
    ("quantity=10 (boundary: enters 10% discount)", 10.0, 10, 10.0 * 10 * 0.9),
    ("quantity=49 (boundary: still 10% discount)", 10.0, 49, 10.0 * 49 * 0.9),
    ("quantity=50 (boundary: enters 25% discount)", 10.0, 50, 10.0 * 50 * 0.75),
    ("quantity=100 (above all thresholds)", 10.0, 100, 10.0 * 100 * 0.75),
};

int passCount = 0;
int failCount = 0;

foreach (var (desc, p, qty, expected) in tests) {
    double got = CalculateDiscount(p, qty);
    if (Math.Abs(got - expected) < tolerance) {
        Console.WriteLine($"PASS: {desc}");
        passCount++;
    } else {
        Console.WriteLine($"FAIL: {desc} (expected: {expected}, got: {got})");
        failCount++;
    }
}

Console.WriteLine($"\nTotal: {passCount + failCount} | Passed: {passCount} | Failed: {failCount}");
